describe('Dropdown Selection', () => {
  beforeEach(() => {
    cy.visit('https://the-internet.herokuapp.com/dropdown');
  });

  it('should display disabled prompt initially', () => {
    cy.get('#dropdown')
      .should('have.value', '')
      .should('contain', 'Please select an option');

    cy.get('#dropdown option:first')
      .should('have.attr', 'disabled')
      .should('have.text', 'Please select an option');
  });

  it('should select Option 2 and update the dropdown value', () => {
    cy.get('#dropdown')
      .select('Option 2');

    cy.get('#dropdown')
      .should('have.value', '2');

    cy.get('#dropdown option:selected')
      .should('have.text', 'Option 2')
      .should('have.value', '2');
  });

  it('should handle selecting different options sequentially', () => {
    cy.get('#dropdown')
      .select('Option 1');

    cy.get('#dropdown')
      .should('have.value', '1');

    cy.get('#dropdown')
      .select('Option 2');

    cy.get('#dropdown')
      .should('have.value', '2');

    cy.get('#dropdown option:selected')
      .should('have.text', 'Option 2');
  });
});
